import{_ as a,E as o,o as i,a as s,d as t,H as r}from"./chunks/framework.IehvnstE.js";const w=JSON.parse('{"title":"Installation","description":"Detailed guide to installing Stuzhik on Windows and Linux. System requirements, the AppImage, .deb and .rpm packages, updating and removing.","frontmatter":{"description":"Detailed guide to installing Stuzhik on Windows and Linux. System requirements, the AppImage, .deb and .rpm packages, updating and removing.","head":[["meta",{"name":"keywords","content":"stuzhik download, install stuzhik, minecraft launcher download, minecraft launcher system requirements"}]]},"headers":[],"relativePath":"en/guide/installation.md","filePath":"en/guide/installation.md"}'),l={name:"en/guide/installation.md"};function d(h,e,u,p,c,g){const n=o("DownloadButton");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>An installer for Windows, packages for Linux: what the computer needs, how to update and how to remove it.</p><h2 id="system-requirements" tabindex="-1">System requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System requirements&quot;">​</a></h2><p>System: <strong>Windows 10 or newer</strong> or <strong>Linux x86_64 with glibc 2.38+</strong> (Debian 13, Ubuntu 24.04, Fedora 39 or newer).</p><table tabindex="0"><thead><tr><th></th><th>Minimum</th><th>Better</th></tr></thead><tbody><tr><td>Memory</td><td>4 GB</td><td>16 GB</td></tr><tr><td>Disk</td><td>2 GB plus room for builds</td><td>SSD, 20 GB free</td></tr><tr><td>Graphics</td><td>OpenGL 3.3</td><td>OpenGL 3.3</td></tr></tbody></table><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2>',6)),r(n),e[1]||(e[1]=t('<ol><li>Download the installer with the button above</li><li>Run it and go through the installer&#39;s steps</li></ol><p>For Linux there are the AppImage, .deb and .rpm: <a href="/en/download.html#linux">Download</a>, how to install and update them is <a href="#linux">below</a>. For Linux servers there is the <a href="/en/guide/cli.html">console version</a>.</p><h2 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h2><p>Stuzhik <strong>checks for and installs updates by itself</strong> at startup. Set it up in «Settings → Updates»:</p><ul><li>«Check for updates on startup»: turn it off if you don&#39;t want automatic updates</li><li>«Update channel»: «Stable» or «Beta»</li></ul><p>To check by hand: «Check now» in the same place, next to the installed version. You can also just download the new installer and run it over the old one: <strong>builds, worlds and settings stay</strong>.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><p>Like any program: Windows Settings → Apps → Stuzhik → Uninstall.</p><ul><li><strong>Always goes</strong>: service data, that is the cache, logs, error reports, the built-in browser&#39;s data, saved account logins (they live in the Windows Credential Manager) and the firewall rule for Stuzhik Connect. To remove the rule, Windows asks for administrator confirmation once, and only if the rule was created</li><li><strong>Only with the checkbox</strong> «Also delete builds and worlds (all launcher data)»: builds, worlds, settings, Java and game files. Without it they stay, and after reinstalling everything is in place</li></ul><p>Updating the launcher touches none of this.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux {#linux}&quot;">​</a></h2><p>The packages and which systems they are for: <a href="/en/download.html#linux">Download → Linux</a>. <strong>It needs x86_64 and glibc 2.38 or newer</strong> (<code>ldd --version</code>).</p><ul><li><strong>Installing.</strong> AppImage: <code>chmod +x Stuzhik_*.AppImage</code> and run the file. .deb: <code>sudo apt install ./Stuzhik_*_amd64.deb</code>. .rpm: <code>sudo dnf install ./Stuzhik-*.x86_64.rpm</code> (openSUSE: <code>sudo zypper install</code>)</li><li><strong>Updating.</strong> As on Windows: the launcher finds a new version by itself. It replaces the AppImage in place; the system installs the .deb and the .rpm and asks for your password once</li><li><strong>Removing.</strong> <code>sudo apt remove stuzhik</code> or <code>sudo dnf remove stuzhik</code>, the AppImage is just deleted. Builds, worlds and settings stay in <code>~/.local/share/ru.sibxodev.stuzhik</code>: delete that folder if you no longer need them</li><li><strong>The AppImage does not start on Ubuntu 24.04.</strong> It needs the FUSE 2 library: <code>sudo apt install libfuse2t64</code>. Or run <code>./Stuzhik_*.AppImage --appimage-extract-and-run</code></li><li><strong>The error «GLIBC_2.38 not found».</strong> The system is older than needed (Debian 12, Ubuntu 22.04), the app does not start there. Servers run on it through the <a href="/en/guide/cli.html">console version</a></li></ul><h2 id="if-the-launcher-won-t-start" tabindex="-1">If the launcher won&#39;t start <a class="header-anchor" href="#if-the-launcher-won-t-start" aria-label="Permalink to &quot;If the launcher won&#39;t start&quot;">​</a></h2><p>On Windows install <a href="https://developer.microsoft.com/en-us/microsoft-edge/webview2/" target="_blank" rel="noreferrer">WebView2 Runtime</a>: it draws the launcher&#39;s window.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#B392F0;">winget</span><span style="color:#9ECBFF;"> install</span><span style="color:#9ECBFF;"> Microsoft.EdgeWebView2Runtime</span></span></code></pre></div>',16))])}const f=a(l,[["render",d]]);export{w as __pageData,f as default};
